CREATE DATABASE IF NOT EXISTS campushire; USE campushire;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role ENUM('student','admin','company') NOT NULL DEFAULT 'student', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS departments (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS students (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL UNIQUE, department_id INT, roll_number VARCHAR(30) UNIQUE, full_name VARCHAR(120) NOT NULL, phone VARCHAR(30), graduation_year YEAR, bio TEXT, resume_url VARCHAR(255), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(department_id) REFERENCES departments(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS industries (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS companies (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT UNIQUE, industry_id INT, name VARCHAR(150) NOT NULL UNIQUE, description TEXT, website VARCHAR(255), location VARCHAR(120), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL, FOREIGN KEY(industry_id) REFERENCES industries(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS internships (id INT AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, title VARCHAR(180) NOT NULL, description TEXT NOT NULL, location VARCHAR(120) NOT NULL, work_mode ENUM('remote','hybrid','on-site') NOT NULL DEFAULT 'on-site', stipend DECIMAL(10,2) DEFAULT 0 CHECK(stipend >= 0), duration_months DECIMAL(4,1) NOT NULL CHECK(duration_months > 0), deadline DATE NOT NULL, start_date DATE, openings INT NOT NULL DEFAULT 1 CHECK(openings > 0), status ENUM('draft','active','closed') NOT NULL DEFAULT 'active', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE, INDEX idx_internship_search(status,deadline,location,work_mode), INDEX idx_internship_company(company_id));
CREATE TABLE IF NOT EXISTS skills (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS student_skills (student_id INT NOT NULL, skill_id INT NOT NULL, proficiency ENUM('beginner','intermediate','advanced') DEFAULT 'intermediate', PRIMARY KEY(student_id,skill_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS internship_skills (internship_id INT NOT NULL, skill_id INT NOT NULL, required BOOLEAN DEFAULT TRUE, PRIMARY KEY(internship_id,skill_id), FOREIGN KEY(internship_id) REFERENCES internships(id) ON DELETE CASCADE, FOREIGN KEY(skill_id) REFERENCES skills(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS applications (id INT AUTO_INCREMENT PRIMARY KEY, student_id INT NOT NULL, internship_id INT NOT NULL, cover_note TEXT, status ENUM('submitted','screening','shortlisted','interview','offered','rejected','withdrawn') DEFAULT 'submitted', applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_application(student_id,internship_id), FOREIGN KEY(student_id) REFERENCES students(id) ON DELETE CASCADE, FOREIGN KEY(internship_id) REFERENCES internships(id) ON DELETE CASCADE, INDEX idx_app_status(status), INDEX idx_app_student(student_id));
CREATE TABLE IF NOT EXISTS interviews (id INT AUTO_INCREMENT PRIMARY KEY, application_id INT NOT NULL, scheduled_at DATETIME NOT NULL, mode ENUM('online','in-person') DEFAULT 'online', meeting_link VARCHAR(255), result ENUM('pending','passed','failed') DEFAULT 'pending', notes TEXT, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS offers (id INT AUTO_INCREMENT PRIMARY KEY, application_id INT NOT NULL UNIQUE, offered_at DATE NOT NULL, response ENUM('pending','accepted','rejected') DEFAULT 'pending', expires_at DATE NOT NULL, FOREIGN KEY(application_id) REFERENCES applications(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS internship_records (id INT AUTO_INCREMENT PRIMARY KEY, offer_id INT NOT NULL UNIQUE, start_date DATE NOT NULL, end_date DATE, status ENUM('upcoming','ongoing','completed') DEFAULT 'upcoming', FOREIGN KEY(offer_id) REFERENCES offers(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS evaluations (id INT AUTO_INCREMENT PRIMARY KEY, record_id INT NOT NULL UNIQUE, score DECIMAL(3,1) NOT NULL CHECK(score BETWEEN 0 AND 10), feedback TEXT, evaluated_at DATE, FOREIGN KEY(record_id) REFERENCES internship_records(id) ON DELETE CASCADE);
